// Claude's review tests for A31 (errors) and A32 (streams) in the fake hub. agy: do not edit this file.
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import type { LogDraft, SocketMock, SocketReply } from '../core/types';
import type { PatchDeps } from './fetchPatch';
import type { Gate, GateConfig } from './gate';
import { installSocketPatch } from './socketPatch';

const RS = '\u001e';
class NativeStub {
  constructor(public url: string) {}
}

function reply(when: string, respond: SocketReply['respond'], result: string): SocketReply {
  return { id: `r-${when}`, when, respond, result, pushes: [] };
}

function setup(replies: SocketReply[], kind: SocketMock['kind'] = 'signalr') {
  const hub: SocketMock = { id: 'hub', enabled: true, kind, urlPattern: '/hub', createdAt: 0, onConnect: [], replies };
  const cfg: GateConfig = { mocks: [], settings: { enabled: true, recording: true }, sockets: [hub] };
  const win = { WebSocket: NativeStub, EventTarget, MessageEvent, location: { href: 'http://a.test/page' } } as unknown as Window;
  const reported: LogDraft[] = [];
  const gate: Gate = { open: vi.fn(), wait: vi.fn(), current: () => cfg };
  const deps: PatchDeps = { gate, report: (d) => reported.push(d), now: () => 0, console: { info: vi.fn(), warn: vi.fn() } };
  installSocketPatch(win, deps);
  const WS = (win as unknown as { WebSocket: new (u: string) => WebSocket }).WebSocket;
  const ws = new WS('ws://a.test/hub');
  const got: string[] = [];
  ws.addEventListener('message', (e) => got.push(String((e as MessageEvent).data)));
  return { ws, got };
}

async function connect(ws: WebSocket, got: string[]) {
  await vi.advanceTimersByTimeAsync(1); // the fake socket opens on the next tick
  ws.send(`{"protocol":"json","version":1}${RS}`);
  await vi.advanceTimersByTimeAsync(1);
  got.length = 0;
}

const parsed = (got: string[]) => got.map((g) => JSON.parse(g.slice(0, -1)) as Record<string, unknown>);

describe('A31: errors like a real hub', () => {
  beforeEach(() => vi.useFakeTimers());
  afterEach(() => vi.useRealTimers());

  it('an unknown method answers "Method does not exist"', async () => {
    const { ws, got } = setup([]);
    await connect(ws, got);
    ws.send(`{"type":1,"invocationId":"0","target":"Nope","arguments":[]}${RS}`);
    await vi.advanceTimersByTimeAsync(5);
    expect(parsed(got)).toEqual([{ type: 3, invocationId: '0', error: "Failed to invoke 'Nope' due to an error on the server. HubException: Method does not exist." }]);
  });

  it('an unknown method sent without an invocationId gets nothing', async () => {
    const { ws, got } = setup([]);
    await connect(ws, got);
    ws.send(`{"type":1,"target":"Nope","arguments":[]}${RS}`);
    await vi.advanceTimersByTimeAsync(5);
    expect(got).toEqual([]);
  });

  it('an error reply answers with its text, or a default text when empty', async () => {
    const { ws, got } = setup([reply('Fail', 'error', 'nope'), reply('Blank', 'error', '')]);
    await connect(ws, got);
    ws.send(`{"type":1,"invocationId":"0","target":"Fail","arguments":[]}${RS}`);
    ws.send(`{"type":1,"invocationId":"1","target":"Blank","arguments":[]}${RS}`);
    await vi.advanceTimersByTimeAsync(5);
    expect(parsed(got)).toEqual([
      { type: 3, invocationId: '0', error: 'nope' },
      { type: 3, invocationId: '1', error: 'An error occurred on the server.' },
    ]);
  });
});

describe('A32: streams', () => {
  beforeEach(() => vi.useFakeTimers());
  afterEach(() => vi.useRealTimers());

  it('a stream reply sends each item 10 ms apart, then the completion', async () => {
    const { ws, got } = setup([reply('Counter', 'stream', '[1,{"n":2},"three"]')]);
    await connect(ws, got);
    ws.send(`{"type":4,"invocationId":"5","target":"Counter","arguments":[3]}${RS}`);
    await vi.advanceTimersByTimeAsync(1);
    expect(parsed(got)).toEqual([{ type: 2, invocationId: '5', item: 1 }]);
    await vi.advanceTimersByTimeAsync(10);
    expect(parsed(got).length).toBe(2);
    await vi.advanceTimersByTimeAsync(30);
    expect(parsed(got)).toEqual([
      { type: 2, invocationId: '5', item: 1 },
      { type: 2, invocationId: '5', item: { n: 2 } },
      { type: 2, invocationId: '5', item: 'three' },
      { type: 3, invocationId: '5' },
    ]);
  });

  it('a cancel stops the stream: no more items and no completion', async () => {
    const { ws, got } = setup([reply('Counter', 'stream', '[1,2,3,4]')]);
    await connect(ws, got);
    ws.send(`{"type":4,"invocationId":"5","target":"Counter","arguments":[]}${RS}`);
    await vi.advanceTimersByTimeAsync(12);
    ws.send(`{"type":5,"invocationId":"5"}${RS}`);
    await vi.advanceTimersByTimeAsync(100);
    expect(parsed(got)).toEqual([{ type: 2, invocationId: '5', item: 1 }, { type: 2, invocationId: '5', item: 2 }]);
  });

  it('a fixed reply to a stream: an array streams its items, anything else is one item', async () => {
    const { ws, got } = setup([reply('Arr', 'fixed', '[7,8]'), reply('One', 'fixed', '{"a":1}')]);
    await connect(ws, got);
    ws.send(`{"type":4,"invocationId":"1","target":"Arr","arguments":[]}${RS}`);
    ws.send(`{"type":4,"invocationId":"2","target":"One","arguments":[]}${RS}`);
    await vi.advanceTimersByTimeAsync(100);
    const m = parsed(got);
    expect(m.filter((x) => x.invocationId === '1')).toEqual([{ type: 2, invocationId: '1', item: 7 }, { type: 2, invocationId: '1', item: 8 }, { type: 3, invocationId: '1' }]);
    expect(m.filter((x) => x.invocationId === '2')).toEqual([{ type: 2, invocationId: '2', item: { a: 1 } }, { type: 3, invocationId: '2' }]);
  });

  it('an error reply to a stream, and a stream with no reply, end with an error completion', async () => {
    const { ws, got } = setup([reply('Bad', 'error', 'stop')]);
    await connect(ws, got);
    ws.send(`{"type":4,"invocationId":"1","target":"Bad","arguments":[]}${RS}`);
    ws.send(`{"type":4,"invocationId":"2","target":"Missing","arguments":[]}${RS}`);
    await vi.advanceTimersByTimeAsync(10);
    expect(parsed(got)).toEqual([
      { type: 3, invocationId: '1', error: 'stop' },
      { type: 3, invocationId: '2', error: "Failed to invoke 'Missing' due to an error on the server. HubException: Method does not exist." },
    ]);
  });

  it('a stream reply to a normal invoke answers the array as one result', async () => {
    const { ws, got } = setup([reply('Counter', 'stream', '[1,2]')]);
    await connect(ws, got);
    ws.send(`{"type":1,"invocationId":"0","target":"Counter","arguments":[]}${RS}`);
    await vi.advanceTimersByTimeAsync(5);
    expect(parsed(got)).toEqual([{ type: 3, invocationId: '0', result: [1, 2] }]);
  });
});
